    SELECT @cnt = COUNT(*) FROM dbo.Product WHERE ProductId = @InventoryCountItemId;
    SELECT * FROM dbo.tvf_StockByProduct(@InventoryCountItemId);
    DELETE FROM dbo.Orders WHERE OrderId = @InventoryCountItemId AND Status = 0;
